# ----------------------------------------------------------------------
# 3️⃣  Optimized model (ModelNew)
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias

        # Attach the custom transposed‑convolution operator.
        self.transpose3d_cuda = transpose3d

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x: input tensor of shape (batch_size, in_channels, depth, height, width)

        Returns:
            output tensor of shape (batch_size, out_channels, depth_out, height_out, width_out)
        """
        # Build learnable weight tensor (out_channels × kernel_size × kernel_size × kernel_size)
        weight = torch.zeros(self.out_channels, self.kernel_size, self.kernel_size, self.kernel_size).to(x.device, dtype=x.dtype)

        # Perform the transposed 3D convolution using the custom CUDA operator.
        return self.transpose3d_cuda(
            x,
            weight,
            x.size(0),          # batch
            self.in_channels,   # in_channels
            self.out_channels,  # out_channels
            self.kernel_size,   # kernel_size
            self.stride,        # stride
            self.padding,       # padding
            self.output_padding, # output_padding
            self.groups,        # groups
            self.bias           # bias
        )
